package io.github.diodeme.ji.artifact.fs;

import io.github.diodeme.ji.artifact.ArtifactId;
import io.github.diodeme.ji.artifact.ArtifactStore;
import io.github.diodeme.ji.artifact.ArtifactValidationReport;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;

/** Validates database references before startup and requires explicit degraded acceptance. */
public final class ArtifactStartupValidator {
    private final ArtifactStore store;
    private final Path reportPath;

    public ArtifactStartupValidator(ArtifactStore store, Path reportPath) {
        if (store == null || reportPath == null) throw new IllegalArgumentException("startup validation requires store and report path");
        this.store = store;
        this.reportPath = reportPath.toAbsolutePath().normalize();
    }

    public Result validate(Collection<ArtifactId> referencedIds, boolean acceptDegraded) {
        ArtifactValidationReport report = store.validate(referencedIds);
        if (report.valid()) return new Result(false, report, Map.of());
        writeReport(report, acceptDegraded);
        if (!acceptDegraded) {
            throw new ArtifactStartupException("artifact.startup_validation_failed", Map.of(
                    "report", reportPath.toString(), "issues", Integer.toString(report.issues().size())));
        }
        var markers = new LinkedHashMap<ArtifactId, UnavailableMarker>();
        report.issues().forEach(issue -> markers.put(issue.artifactId(),
                new UnavailableMarker("artifact.unavailable", issue.kind().name().toLowerCase(java.util.Locale.ROOT))));
        return new Result(true, report, markers);
    }

    private void writeReport(ArtifactValidationReport report, boolean accepted) {
        try {
            Path parent = reportPath.getParent();
            if (parent == null) throw new IOException("validation report has no parent");
            Files.createDirectories(parent);
            Path temporary = Files.createTempFile(parent, ".artifact-validation-", ".tmp");
            try {
                var body = new StringBuilder("{\n  \"schemaVersion\":1,\n  \"createdAt\":\"")
                        .append(Instant.now()).append("\",\n  \"degradedAccepted\":").append(accepted)
                        .append(",\n  \"issues\":[");
                for (int index = 0; index < report.issues().size(); index++) {
                    if (index > 0) body.append(',');
                    var issue = report.issues().get(index);
                    body.append("\n    {\"artifactId\":\"").append(issue.artifactId().value())
                            .append("\",\"kind\":\"").append(issue.kind().name()).append("\"}");
                }
                body.append("\n  ]\n}\n");
                Files.writeString(temporary, body, StandardCharsets.UTF_8);
                try {
                    Files.move(temporary, reportPath, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
                } catch (java.nio.file.AtomicMoveNotSupportedException unsupported) {
                    Files.move(temporary, reportPath, StandardCopyOption.REPLACE_EXISTING);
                }
            } finally {
                Files.deleteIfExists(temporary);
            }
        } catch (IOException failure) {
            throw new ArtifactStartupException("artifact.validation_report_failed", Map.of("report", reportPath.toString()));
        }
    }

    public record Result(boolean degraded, ArtifactValidationReport report,
                         Map<ArtifactId, UnavailableMarker> markers) {
        public Result { markers = Map.copyOf(markers); }
    }
    public record UnavailableMarker(String code, String reason) {}
}
